import jwt

from app.config import Config


def create_access_token(user_id):
    now = datetime.now(timezone.utc)
    payload = {
        "sub": user_id,
        "type": "access",
        "iat": now,
        "exp": now + Config.ACCESS_TOKEN_EXPIRY,
    }
    return jwt.encode(payload, Config.SECRET_KEY, algorithm="HS256")


def create_refresh_token(user_id):
    now = datetime.now(timezone.utc)
    payload = {
        "sub": user_id,
        "type": "refresh",
        "iat": now,
        "exp": now + Config.REFRESH_TOKEN_EXPIRY,
    }
    return jwt.encode(payload, Config.SECRET_KEY, algorithm="HS256")


def decode_token(token):
    return jwt.decode(token, Config.SECRET_KEY, algorithms=["HS256"])


def decode_seconds_to_expiry(delta):
    if isinstance(delta, int):
        return delta
    return int(delta.total_seconds())

from functools import wraps

from flask import g, jsonify, request

from app.auth.jwt import decode_token
from app.models import User


def login_required(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        auth_header = request.headers.get("Authorization", "")
        if not auth_header.startswith("Bearer "):
            return jsonify({"error": "missing or invalid authorization header"}), 401

        token = auth_header.split(" ", 1)[1]
        try:
            payload = decode_token(token)
        except Exception:
            return jsonify({"error": "invalid or expired token"}), 401

        if payload.get("type") != "access":
            return jsonify({"error": "invalid token type"}), 401

        user = User.query.get(payload["sub"])
        if user is None:
            return jsonify({"error": "user not found"}), 401

        g.current_user = user
        return f(*args, **kwargs)

    return decorated

import threading
import time
from collections import defaultdict

from flask import jsonify, request


class RateLimiter:
    def __init__(self):
        self._lock = threading.Lock()
        self._attempts = defaultdict(list)

    def _cleanup(self, ip):
        now = time.time()
        window = now - 60
        self._attempts[ip] = [t for t in self._attempts[ip] if t > window]

    def is_rate_limited(self, ip, max_attempts=5, window_seconds=60):
        with self._lock:
            self._cleanup(ip)
            if len(self._attempts[ip]) >= max_attempts:
                return True
            self._attempts[ip].append(time.time())
            return False


_rate_limiter = RateLimiter()


def login_rate_limit(f):
    from functools import wraps

    @wraps(f)
    def decorated(*args, **kwargs):
        ip = request.remote_addr or "127.0.0.1"
        if _rate_limiter.is_rate_limited(ip):
            return jsonify({"error": "rate limit exceeded, try again later"}), 429
        return f(*args, **kwargs)

    return decorated

