from werkzeug.exceptions import HTTPException


def register_error_handlers(app):
    @app.errorhandler(400)
    def bad_request(error):
        return jsonify({"error": "bad request", "message": str(error)}), 400

    @app.errorhandler(401)
    def unauthorized(error):
        return jsonify({"error": "unauthorized", "message": str(error)}), 401

    @app.errorhandler(403)
    def forbidden(error):
        return jsonify({"error": "forbidden", "message": str(error)}), 403

    @app.errorhandler(404)
    def not_found(error):
        return jsonify({"error": "not found", "message": str(error)}), 404

    @app.errorhandler(405)
    def method_not_allowed(error):
        return jsonify({"error": "method not allowed", "message": str(error)}), 405

    @app.errorhandler(429)
    def too_many_requests(error):
        return jsonify({"error": "too many requests", "message": str(error)}), 429

    @app.errorhandler(500)
    def internal_error(error):
        return jsonify({"error": "internal server error"}), 500

    @app.errorhandler(HTTPException)
    def handle_http_exception(error):
        return (
            jsonify({"error": error.name.lower().replace(" ", "_"), "message": error.description}),
            error.code,
        )

from flask import Blueprint, jsonify, request

from app.auth.jwt import create_access_token, create_refresh_token, decode_token
from app.extensions import db
from app.middleware.ratelimit import login_rate_limit
from app.models import AuditLog, User
from app.validators import (
    LoginSchema,
    RefreshSchema,
    RegisterSchema,
    validate_schema,
)

bp = Blueprint("auth", __name__, url_prefix="/v1/auth")


@bp.route("/register", methods=["POST"])
@validate_schema(RegisterSchema)
def register(validated_data):
    username = validated_data["username"]
    email = validated_data["email"]
    password = validated_data["password"]

    if User.query.filter_by(email=email).first():
        return jsonify({"error": "email already registered"}), 409

    if User.query.filter_by(username=username).first():
        return jsonify({"error": "username already taken"}), 409

    user = User(username=username, email=email)
    user.set_password(password)
    db.session.add(user)
    db.session.commit()

    access_token = create_access_token(user.id)
    refresh_token = create_refresh_token(user.id)

    AuditLog.log(
        user_id=user.id,
        action="register",
        resource="user",
        resource_id=user.id,
        ip_address=request.remote_addr,
    )

    return jsonify({
        "user": user.to_dict(),
        "access_token": access_token,
        "refresh_token": refresh_token,
    }), 201


@bp.route("/login", methods=["POST"])
@login_rate_limit
@validate_schema(LoginSchema)
def login(validated_data):
    email = validated_data["email"]
    password = validated_data["password"]

    user = User.query.filter_by(email=email).first()
    if user is None or not user.check_password(password):
        return jsonify({"error": "invalid email or password"}), 401

    access_token = create_access_token(user.id)
    refresh_token = create_refresh_token(user.id)

    return jsonify({
        "user": user.to_dict(),
        "access_token": access_token,
        "refresh_token": refresh_token,
    }), 200


@bp.route("/refresh", methods=["POST"])
@validate_schema(RefreshSchema)
def refresh(validated_data):
    refresh_token = validated_data["refresh_token"]

    try:
        payload = decode_token(refresh_token)
    except Exception:
        return jsonify({"error": "invalid or expired refresh token"}), 401

    if payload.get("type") != "refresh":
        return jsonify({"error": "invalid token type"}), 401

    user = User.query.get(payload["sub"])
    if user is None:
        return jsonify({"error": "user not found"}), 401

    new_access = create_access_token(user.id)
    new_refresh = create_refresh_token(user.id)

    return jsonify({
        "access_token": new_access,
        "refresh_token": new_refresh,
    }), 200

from flask import Blueprint, g, jsonify, request

from app.extensions import db
from app.middleware.auth import login_required
from app.models import AuditLog, Item
from app.validators import ItemCreateSchema, ItemUpdateSchema, validate_schema

bp = Blueprint("items", __name__, url_prefix="/v1")


def paginate(query, page, per_page):
    per_page = min(per_page, 100)
    total = query.count()
    items = query.limit(per_page).offset((page - 1) * per_page).all()
    total_pages = (total + per_page - 1) // per_page if per_page else 0
    return {
        "items": [item.to_dict() for item in items],
        "page": page,
        "per_page": per_page,
        "total": total,
        "total_pages": total_pages,
    }


@bp.route("/items", methods=["GET"])
@login_required
def list_items():
    page = request.args.get("page", 1, type=int)
    per_page = request.args.get("per_page", 20, type=int)

    if page < 1:
        page = 1
    if per_page < 1:
        per_page = 20

    query = Item.query.order_by(Item.created_at.desc())
    result = paginate(query, page, per_page)
    return jsonify(result), 200


@bp.route("/items/<int:item_id>", methods=["GET"])
@login_required
def get_item(item_id):
    item = Item.query.get(item_id)
    if item is None:
        return jsonify({"error": "item not found"}), 404
    return jsonify(item.to_dict()), 200


@bp.route("/items", methods=["POST"])
@login_required
@validate_schema(ItemCreateSchema)
def create_item(validated_data):
    item = Item(
        name=validated_data["name"],
        description=validated_data.get("description"),
        price=validated_data["price"],
        owner_id=g.current_user.id,
    )
    db.session.add(item)
    db.session.commit()

    AuditLog.log(
        user_id=g.current_user.id,
        action="create",
        resource="item",
        resource_id=item.id,
        details=f"Created item '{item.name}'",
        ip_address=request.remote_addr,
    )

    return jsonify(item.to_dict()), 201


@bp.route("/items/<int:item_id>", methods=["PUT"])
@login_required
@validate_schema(ItemUpdateSchema)
def update_item(item_id, validated_data):
    item = Item.query.get(item_id)
    if item is None:
        return jsonify({"error": "item not found"}), 404

    if item.owner_id != g.current_user.id:
        return jsonify({"error": "forbidden"}), 403

    if not validated_data:
        return jsonify({"error": "no fields to update"}), 400

    for key, value in validated_data.items():
        if value is not None:
            setattr(item, key, value)

    db.session.commit()

    AuditLog.log(
        user_id=g.current_user.id,
        action="update",
        resource="item",
        resource_id=item.id,
        details=f"Updated item '{item.name}'",
        ip_address=request.remote_addr,
    )

    return jsonify(item.to_dict()), 200


@bp.route("/items/<int:item_id>", methods=["DELETE"])
@login_required
def delete_item(item_id):
    item = Item.query.get(item_id)
    if item is None:
        return jsonify({"error": "item not found"}), 404

    if item.owner_id != g.current_user.id:
        return jsonify({"error": "forbidden"}), 403

    db.session.delete(item)
    db.session.commit()

    AuditLog.log(
        user_id=g.current_user.id,
        action="delete",
        resource="item",
        resource_id=item_id,
        details=f"Deleted item '{item.name}'",
        ip_address=request.remote_addr,
    )

    return jsonify({"message": "item deleted"}), 200

